<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Status='待补资料'|'待审核'|'已生效'|'待支付'|'待生产'|'生产中'|'待质检'|'待发货'|'运输中'|'已签收'|'复测中'|'已完成'
interface Formula {skuCode:string;name:string;ratio:number;dosage:string;rationale:string;machineParams:string;valid:boolean;stockAvailable:boolean}
interface Case {id:string;customer:string;status:Status;risk:string;planId:string;planVersion:string;reportStatus:string;paid:boolean;qualityReleased:boolean;formula:Formula[];timeline:any[]}
const tab=ref<'home'|'assess'|'plan'|'orders'|'mine'>('home'); const step=ref(1); const answers=ref<Record<string,any>>({}); const uploaded=ref(false); const accepted=ref(false); const cases=ref<Case[]>([]); const selected=ref<Case|null>(null); const notice=ref(''); const reportName=ref('');
const questions=[
  {id:'sleep',dimension:'基础状态',desc:'用于了解当前精力、睡眠和疲劳情况',title:'近两周你的睡眠质量如何？',type:'single',options:['很好，入睡和醒来都较稳定','一般，偶尔失眠或早醒','较差，经常难以入睡或夜醒']},
  {id:'feeling',dimension:'基础状态',desc:'用于了解当前精力、睡眠和疲劳情况',title:'你最近最明显的身体感受是？',type:'multi',options:['易疲劳','睡眠浅','精力不足','皮肤状态下滑']},
  {id:'exercise',dimension:'生活方式',desc:'用于识别饮食、运动和恢复节律',title:'你每周的运动频率是？',type:'single',options:['基本不运动','每周 1-2 次','每周 3 次及以上']},
  {id:'stress',dimension:'压力情绪',desc:'用于识别恢复与压力状态',title:'近两周压力感受如何？',type:'single',options:['轻度','中等','明显且影响生活']},
  {id:'safety',dimension:'健康安全',desc:'用于安全复核，不替代医生诊断',title:'是否正在使用重要药物或存在需持续管理的情况？',type:'single',options:['否','是','不确定']},
]
const doneCount=computed(()=>questions.filter(q=>Array.isArray(answers.value[q.id])?answers.value[q.id].length:answers.value[q.id]).length)
const canSubmit=computed(()=>doneCount.value===questions.length&&uploaded.value&&accepted.value)
async function load(){try{const r=await fetch('/api/cases',{headers:{authorization:'Bearer customer'}});cases.value=(await r.json()).data;selected.value=cases.value[0]||null}catch{notice.value='本地服务未连接，请先启动 pnpm dev'}}
function choose(q:any,op:string){if(q.type==='multi'){const values=answers.value[q.id]||[];answers.value[q.id]=values.includes(op)?values.filter((x:string)=>x!==op):[...values,op]}else answers.value[q.id]=op}
function pickFile(e:any){const file=e.target.files?.[0];if(!file)return;const ok=/\.(pdf|doc|docx)$/i.test(file.name);if(!ok){notice.value='仅支持 PDF、DOC、DOCX 格式';return}if(file.size>20*1024*1024){notice.value='单个报告不能超过 20MB';return}uploaded.value=true;reportName.value=file.name;notice.value='文件已上传，正在本地模拟解析'}
async function submit(){if(!canSubmit.value){notice.value='请完成所有必答题、报告上传并同意服务声明';return}try{const r=await fetch(`/api/cases/${selected.value?.id}/submit`,{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer customer'},body:JSON.stringify({complete:true})});const j=await r.json();if(!r.ok)throw Error(j.message);notice.value='测评已提交，正在等待专业审核';await load();tab.value='plan'}catch(e:any){notice.value=e.message}}
async function pay(){if(!selected.value)return;try{const r=await fetch(`/api/cases/${selected.value.id}/pay`,{method:'POST',headers:{authorization:'Bearer customer'}});const j=await r.json();if(!r.ok)throw Error(j.message);notice.value='支付成功，订单已进入总部生产';await load()}catch(e:any){notice.value=e.message}}
const planTitle=computed(()=>selected.value?.status==='待审核'?'方案正在专业审核':selected.value?.status==='待补资料'?'请补充测评资料':selected.value?.status==='已生效'?'您的健康管理方案已生效':'方案服务进行中')
onMounted(load)
</script>
<template>
 <view class="app">
  <view v-if="notice" class="notice" @click="notice=''">{{notice}} <text>×</text></view>
  <template v-if="tab==='home'"><view class="hero"><text class="eyebrow">LAVIDA · PERSONAL WELLNESS</text><text class="hello">你好，林若溪</text><text class="sub">从一次测评开始，获得可追溯的健康管理服务。</text><button @click="tab='assess'">开始健康测评</button></view><view class="section-head"><text>我的健康服务</text><text @click="tab='plan'">查看全部 ›</text></view><view class="service-grid"><view class="service" @click="tab='assess'"><text class="icon">◎</text><b>智能测评</b><small>必答问卷与报告上传</small></view><view class="service" @click="tab='plan'"><text class="icon">✦</text><b>方案中心</b><small>{{selected?.status||'等待服务'}}</small></view><view class="service" @click="tab='orders'"><text class="icon">□</text><b>订单履约</b><small>生产、物流与签收</small></view></view><view class="section-head"><text>健康资讯</text><text>更多 ›</text></view><view class="article"><b>睡眠质量与恢复节律</b><small>健康管理建议 · 阅读 1,286</small><p>建立稳定作息、规律运动与均衡营养，是改善恢复节律的基础。</p></view><view class="article"><b>抗氧化饮食的日常提示</b><small>健康资讯 · 阅读 986</small><p>本文仅提供一般健康管理信息，不能替代医疗建议。</p></view></template>
  <template v-else-if="tab==='assess'"><view class="top"><text @click="tab='home'">‹</text><b>问卷填写</b><text>暂存</text></view><view class="progress-card"><b>问卷填写</b><small>已完成 {{doneCount}}/{{questions.length}} 题</small><view class="bar"><view :style="{width:(doneCount/questions.length*100)+'%'}"></view></view></view><view v-for="q in questions" :key="q.id" class="question-card"><b class="dim">{{q.dimension}}</b><small>{{q.desc}}</small><view class="q-title">{{q.title}} <em>必填</em></view><small v-if="q.type==='multi'">可多选</small><view class="options"><button v-for="op in q.options" :key="op" :class="{picked:q.type==='multi'?(answers[q.id]||[]).includes(op):answers[q.id]===op}" @click="choose(q,op)">{{op}}</button></view></view><view class="upload-card"><b>检查报告上传 <em>必填</em></b><small>支持 PDF、DOC、DOCX；单个文件不超过 20MB。</small><label class="upload"><input type="file" accept=".pdf,.doc,.docx" @change="pickFile"/>{{uploaded?'已上传：'+reportName:'选择检查报告'}}</label><view v-if="uploaded" class="parse">✓ 已完成安全校验 · 正在生成结构化摘要</view></view><label class="agreement"><input type="checkbox" v-model="accepted"/> 我已阅读并同意健康管理服务与隐私声明</label><view class="bottom-actions"><button @click="notice='问卷草稿已暂存'">暂存</button><button class="primary" :disabled="!canSubmit" @click="submit">保存问卷并继续上传</button></view></template>
  <template v-else-if="tab==='plan'"><view class="top"><text @click="tab='home'">‹</text><b>方案中心</b><text></text></view><view class="status-card"><text class="eyebrow">{{selected?.planId||'PLAN-待生成'}}</text><h2>{{planTitle}}</h2><p>状态：{{selected?.status||'暂无方案'}} · {{selected?.planVersion||'--'}}</p><view class="steps"><text>测评提交</text><text>智能分析</text><text :class="{on:selected?.status!=='待审核'}">专业审核</text><text :class="{on:['已生效','待支付','待生产','生产中','待质检','待发货','运输中','已签收','复测中','已完成'].includes(selected?.status||'')}">方案生效</text></view></view><template v-if="selected?.status==='已生效'"><view class="card"><b>健康管理摘要</b><p>睡眠与精力恢复建议改善；请保持规律作息、均衡饮食并完成复测。该内容不构成诊断或处方。</p><view class="chips"><text>睡眠支持</text><text>精力管理</text><text>抗氧化</text></view></view><view class="card"><b>商品组合与配方摘要</b><view v-for="f in selected.formula" :key="f.skuCode" class="formula"><view><strong>{{f.name}}</strong><small>{{f.skuCode}} · {{f.ratio}}%</small></view><text>{{f.dosage}}</text></view></view><view class="card safety"><b>安全说明</b><p>如处于妊娠/哺乳期、存在过敏或正在使用药物，请先咨询专业人士。系统建议不能替代就医。</p></view><view class="bottom-actions"><button @click="notice='方案免责声明已阅读'">查看版本</button><button class="primary" @click="tab='orders'">确认方案并下单</button></view></template><view v-else class="empty-state"><text class="big">✦</text><b>{{selected?.status==='待补资料'?'请补充资料后重新提交':'专业审核进行中'}}</b><small>审核通过后将展示完整商品组合与配方建议。</small><button v-if="selected?.status==='待补资料'" @click="tab='assess'">补充资料</button></view></template>
  <template v-else-if="tab==='orders'"><view class="top"><text @click="tab='home'">‹</text><b>订单与履约</b><text></text></view><view class="order-card"><text class="eyebrow">{{selected?.id||'暂无订单'}}</text><h2>{{selected?.status||'暂无订单'}}</h2><p>{{selected?.planId}} · 总部统一生产并直发顾客</p><view class="order-line"><span>方案商品组合</span><b>¥ 3,980.00</b></view><view class="order-line"><span>配送服务</span><b>¥ 0.00</b></view><view class="order-line total"><span>应付金额</span><b>¥ 3,980.00</b></view><button v-if="selected?.status==='已生效'" class="primary wide" @click="pay">确认订单并模拟支付</button><button v-else class="wide" @click="tab='plan'">查看方案服务状态</button></view><view class="card"><b>履约时间线</b><view v-for="t in selected?.timeline" :key="t.time+t.title" class="track"><i></i><view><b>{{t.title}}</b><small>{{t.time}} · {{t.description}}</small></view></view></view><view class="card"><b>售后与服务追踪</b><p>支持查看物流、签收、异常补发、复测提醒与历史服务记录。</p><button @click="notice='售后申请入口已记录到演示任务'">申请售后</button></view></template>
  <template v-else><view class="top"><text @click="tab='home'">‹</text><b>我的</b><text>设置</text></view><view class="profile"><view class="avatar">林</view><view><h2>林若溪</h2><small>高阶服务用户 · 上海静安体验店</small></view></view><view class="asset"><view><b>2</b><small>历史测评</small></view><view><b>3</b><small>方案版本</small></view><view><b>1</b><small>服务订单</small></view></view><view class="list"><view><span>我的资料与授权</span><text>›</text></view><view><span>历史测评与复测</span><text>›</text></view><view><span>消息中心</span><text>›</text></view><view><span>隐私政策与账户设置</span><text>›</text></view></view></template>
  <view class="tabbar"><button :class="{on:tab==='home'}" @click="tab='home'">首页</button><button :class="{on:tab==='assess'}" @click="tab='assess'">测评</button><button :class="{on:tab==='plan'}" @click="tab='plan'">方案</button><button :class="{on:tab==='orders'}" @click="tab='orders'">订单</button><button :class="{on:tab==='mine'}" @click="tab='mine'">我的</button></view>
 </view>
</template>
